def _tab_html(tab,height=360,font='13px'):
    """将 DataFrame 渲染为字符居中的 HTML 表格（网格画布无法居中单元格文字）。"""
    cols=[str(c) for c in tab.columns]
    head=''.join('<th style="text-align:center;padding:7px 12px;border:1px solid #dedee3;background:#f2f3f7;font-weight:600;white-space:nowrap;">'+html.escape(c)+'</th>' for c in cols)
    body=[]
    def _fmt(v):
        if pd.isna(v): return ''
        if isinstance(v,(int,np.integer)): return str(int(v))
        if isinstance(v,float):
            if not math.isfinite(v): return str(v)
            s=f'{v:.4f}'
            return s.rstrip('0').rstrip('.') if '.' in s else s
        return str(v)
    for i,(_,r) in enumerate(tab.iterrows()):
        bg='#ffffff' if i%2==0 else '#fafbfc'
        tds=''.join('<td style="text-align:center;padding:6px 12px;border:1px solid #e8e8ed;background:'+bg+';">'+html.escape(_fmt(v))+'</td>' for v in r)
        body.append('<tr>'+tds+'</tr>')
    return ('<div style="max-height:'+str(height)+'px;overflow:auto;border:1px solid #dedee3;border-radius:10px;font-size:'+font+';background:#fff;">'
            '<table style="border-collapse:collapse;width:100%;">'
            '<thead style="position:sticky;top:0;z-index:1;"><tr>'+head+'</tr></thead>'
            '<tbody>'+''.join(body)+'</tbody></table></div>')



