import base64, zlib, math
FIELD_MAPPING = {'city': '城市', 'year': '年份', 'Inn_w': '区域创新生态指数', 'subject_index_w': '创新主体指数', 'resource_index_w': '资源配置指数', 'flow_index_w': '要素流动指数', 'resilience_index_w': '创新韧性指数', 'gfund_w': '人民币百万_插值最终结果', 'Coop_w': '产学研合作', 'tech_contract_w': '技术合同成交额（万元）', 'rd_intensity_w': '研发投入强度', 'digital_index_w': '数字普惠金融指数', 'high_market': '市场化分组码', 'marketing': '市场化水平', 'gfund': '原始基金（百万元）'}
EMBEDDED_PANEL = ''
EDIT_COLUMNS = ['城市','年份',INDEX,*DIMS,FUND,'产学研合作','技术合同成交额（万元）','研发投入强度','数字普惠金融指数','市场化分组码']

def validate_panel(raw):
    raw=raw.copy()
    missing=set(EDIT_COLUMNS)-set(raw.columns)
    if missing: raise ValueError('缺少字段：'+ '、'.join(sorted(missing)))
    if raw['城市'].isna().any(): raise ValueError('城市不能为空')
    raw['城市']=raw['城市'].astype(str).str.strip()
    if raw['城市'].eq('').any(): raise ValueError('城市不能为空')
    for col in EDIT_COLUMNS[1:]:
        raw[col]=pd.to_numeric(raw[col],errors='raise')
        if not np.isfinite(raw[col]).all(): raise ValueError(col+'必须填写有限数值')
    if (raw['年份']%1!=0).any() or not raw['年份'].between(1900,2100).all(): raise ValueError('年份应为1900—2100的整数')
    raw['年份']=raw['年份'].astype(int)
    if raw.duplicated(['城市','年份']).any(): raise ValueError('城市与年份组合重复，请修改原行，不要重复新增')
    if ((raw[[INDEX,*DIMS]]<0)|(raw[[INDEX,*DIMS]]>1)).any().any(): raise ValueError('指数须在0—1之间')
    if (raw[[FUND,'产学研合作','技术合同成交额（万元）','研发投入强度','数字普惠金融指数']]<0).any().any(): raise ValueError('规模与投入指标不能为负')
    if not raw['市场化分组码'].isin([0,1]).all(): raise ValueError('市场化分组码须为0（低）或1（高）')
    raw['城市层级']=np.where(raw['城市'].isin(CORE),'核心城市','非核心城市')
    return raw.reset_index(drop=True)

def scenario(fund, growth, beta, se, year):
    # fund is in RMB million, exactly as ln_gfund=ln(1+gfund_w) in Stata.
    if not all(math.isfinite(float(v)) for v in [fund,growth,beta,se,year]) or fund<0 or not 0<=growth<=1 or se<0:
        raise ValueError('情景参数无效')
    dx=(math.log1p(fund*(1+growth))-math.log1p(fund)) if year>=2015 else 0.
    return dict(dx=dx,delta=beta*dx,lower=(beta-1.96*se)*dx,upper=(beta+1.96*se)*dx,fund_after=fund*(1+growth))

def report_markdown(d, sim=None, group=None):
    text=f"# {d['city']}创新生态研究简报\n\n年份：{d['year']}；指数：{d['index']:.6f}；排名：{d['rank']}/{d['n']}。\n\n相对短板：{d['weak']}。{d['action']}\n"
    if sim: text+=f"\n系数组：{group}；条件变化：{sim['delta']:.6f}；系数近似区间：[{sim['lower']:.6f}, {sim['upper']:.6f}]。基金规模单位：百万元。\n"
    return text+'\n数据来自新版DTA或当前会话编辑值；手工编辑不会自动重估论文系数。条件情景不是实际政策效果预测。机制回归样本与基准不同，不据此计算中介占比。'

@st.cache_data(show_spinner=False)
def get_data(payload=None):
    raw=pd.read_csv(io.BytesIO(payload)) if payload else pd.read_json(io.StringIO(zlib.decompress(base64.b64decode(EMBEDDED_PANEL)).decode()))
    return validate_panel(raw)


