def draw(fig, height=360, **kwargs):
    fig.update_layout(template='plotly_white',height=height,margin=dict(l=15,r=20,t=35,b=30),
                      paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='#ffffff',
                      font=dict(family='Microsoft YaHei, Arial, sans-serif',color='#1d1d1f'),
                      colorway=['#0071e3','#34c759','#ff9f0a','#af52de'],legend=dict(orientation='h',y=-.17))
    fig.update_xaxes(gridcolor='#eeeeF2',zerolinecolor='#d2d2d7')
    fig.update_yaxes(gridcolor='#eeeeF2',zerolinecolor='#d2d2d7')
    return st.plotly_chart(fig,**kwargs)

